"""Dataset report: reads the generated files and writes docs/dataset.md.

Regenerated from the data every time, so the numbers in the write-up can't drift.
Run `uv run python -m orgchart.generator.report` after generating the dataset.
"""

import csv
import random
import re
from collections import Counter, defaultdict
from pathlib import Path
from statistics import median

from .fields import MONTHS, parse_location
from .generate import DATA_DIR
from .templates import LEVEL_NAMES, MGR
from .vocabulary import canonical_titles

DOC = Path(__file__).resolve().parents[2] / "docs" / "dataset.md"
LEVELS = ["clean", "medium", "messy"]


def _read(name: str) -> list[dict]:
    with open(DATA_DIR / name, newline="") as f:
        return list(csv.DictReader(f))


def _ym(s: str) -> tuple[int, int | None] | None:
    """Decode any date format the generator writes."""
    if not s:
        return None
    if re.fullmatch(r"\d{4}", s):
        return int(s), None
    if m := re.fullmatch(r"(\d{4})[-/](\d{2})", s):
        return int(m[1]), int(m[2])
    if m := re.fullmatch(r"(\d{1,2})/(\d{4})", s):
        return int(m[2]), int(m[1])
    month, year = s.split(" ")
    return int(year), [x[: len(month)] for x in MONTHS].index(month) + 1


def _table(headers: list[str], rows: list[list]) -> str:
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    out += ["| " + " | ".join(str(c).replace("|", "\\|") for c in r) + " |" for r in rows]
    return "\n".join(out)


def _pct(n: float, d: float) -> str:
    if not d:
        return "-"
    return f"{n / d:.1%}" if 0 < n / d < 0.01 else f"{n / d:.0%}"


def build() -> str:
    companies, people = _read("companies.csv"), _read("people.csv")
    truth, tcomp, tree = _read("truth/people.csv"), _read("truth/companies.csv"), _read("truth/true_tree.csv")
    pub = {p["record_id"]: p for p in people}
    tru = {t["record_id"]: t for t in truth}
    level_of = {c["company_id"]: c["mess_level"] for c in tcomp}
    by_level = defaultdict(list)
    for t in truth:
        by_level[level_of[t["company_id"]]].append(t)
    s = []

    # 1. Shape -----------------------------------------------------------------------------
    emp = Counter(t["company_id"] for t in truth if t["kind"] == "employee")
    kinds = Counter(t["kind"] for t in truth)
    s.append("# Dataset report\n\n_Generated by `orgchart/generator/report.py` from the data in `data/`. "
             "Rebuild both with `uv run python -m orgchart.generator.generate && uv run python -m "
             "orgchart.generator.report`._\n")
    s.append("## 1. Shape\n")
    s.append(_table(["", ""], [
        ["Companies", f"{len(companies):,}"],
        ["Real people (true org trees)", f"{len(tree):,}"],
        ["Records in `people.csv`", f"{len(people):,}"],
        ["…employees / ghosts / duplicates", f"{kinds['employee']:,} / {kinds['ghost']:,} / {kinds['duplicate']:,}"],
        ["Visible employees per company", f"min {min(emp.values())}, median {int(median(emp.values()))}, "
                                          f"max {max(emp.values())}"],
    ]))
    ind = Counter(c["industry"] for c in companies)
    bands = Counter(c["headcount_band"] for c in companies)
    lv = Counter(level_of.values())
    s.append("\n**Industries:** " + ", ".join(f"{k} {v}" for k, v in ind.most_common()))
    s.append("\n**Headcount bands:** " + ", ".join(f"{k}: {bands[k]}" for k in sorted(bands, key=lambda b: int(b.split("-")[0].rstrip("+")))))
    s.append("\n**Mess levels:** " + ", ".join(f"{k} {lv[k]}" for k in LEVELS) + "\n")

    # 2. Titles ------------------------------------------------------------------------------
    canon = {t["canonical_title"] for t in truth}
    base = {c.split(" - ")[0] for c in canon}
    raw = {pub[t["record_id"]]["title"] for t in truth if pub[t["record_id"]]["title"]}
    s.append("## 2. How messy the titles are\n")
    s.append(f"{len(canonical_titles())} canonical roles, at their seniority levels, give {len(base)} true job titles "
             f"({len(canon)} counting team-qualified sub-head titles such as _Head of Risk - Credit Risk_). "
             f"In `people.csv` they appear as **{len(raw):,} distinct raw title strings**.\n")
    role = "Engineering Manager"
    spellings = Counter(pub[t["record_id"]]["title"] for t in truth if t["canonical_title"] == role
                        and pub[t["record_id"]]["title"])
    s.append(f"Every person whose real title is _{role}_ ({sum(spellings.values())} records) is written as one of "
             f"{len(spellings)} strings. The 15 most common:\n")
    s.append(_table(["Raw title", "Records"], [[f"`{k}`", v] for k, v in spellings.most_common(15)]))

    # 3. Fields and mess rates -------------------------------------------------------------------
    s.append("\n## 3. Field completeness and mess rates by mess level\n")
    fields = ["title", "department", "location", "start_date", "prev_employer"]
    s.append(_table(["Blank field"] + LEVELS, [
        [f] + [_pct(sum(not pub[t["record_id"]][f] for t in by_level[l]), len(by_level[l])) for l in LEVELS]
        for f in fields]))
    tag_counts = {l: Counter(tag for t in by_level[l] for tag in t["mess_tags"].split(";") if tag) for l in LEVELS}
    tags = ["variant", "seniority_format", "team", "stale", "inflated", "vague", "creative", "acting", "fluff",
            "typo", "casing", "contractor", "skip_level", "dept_leak", "dept_wrong", "remote", "year_only"]
    s.append("\n")
    s.append(_table(["Mess tag (share of records)"] + LEVELS,
                    [[f"`{tag}`"] + [_pct(tag_counts[l][tag], len(by_level[l])) for l in LEVELS] for tag in tags]))

    # 4. Difficulty ----------------------------------------------------------------------------------
    s.append("\n## 4. How hard the problem is\n")
    lines = [t for t in truth if t["kind"] == "employee" and t["expected_manager_id"]]
    hops = Counter(int(t["hops"]) for t in lines)
    by_company_title = Counter((t["company_id"], t["canonical_title"]) for t in truth if t["kind"] != "duplicate")
    ambiguous = sum(by_company_title[(t["company_id"], tru[t["expected_manager_id"]]["canonical_title"])] > 1
                    for t in lines)
    ghost_mgr_titles = sum(int(t["level"]) <= MGR for t in truth if t["kind"] == "ghost")
    s.append(_table(["", ""], [
        ["Reporting lines to recover", f"{len(lines):,}"],
        ["…direct (manager visible)", f"{hops[0]:,} ({_pct(hops[0], len(lines))})"],
        ["…skip-level (1 / 2 / 3+ bosses missing)",
         f"{hops[1]:,} / {hops[2]:,} / {sum(v for k, v in hops.items() if k >= 3):,}"],
        ["Lines whose boss shares their *real* title with another record in the company "
         "(title alone can't decide)", f"{ambiguous:,} ({_pct(ambiguous, len(lines))})"],
        ["Ghost records (must never be anyone's manager)", f"{kinds['ghost']:,}, of which {ghost_mgr_titles:,} "
                                                            "hold a manager-level title"],
    ]))

    # 5. Clue strength after mess -------------------------------------------------------------------------
    s.append("\n## 5. How strong each clue still is (measured on the public data)\n")
    s.append("For every direct reporting line, how often the clue points at the real manager, and how often it is "
             "unusable (blank or unparseable) on one side.\n")
    rows = []
    for l in LEVELS:
        ls = [t for t in by_level[l] if t["kind"] == "employee" and t["expected_manager_id"] and t["hops"] == "0"]
        loc_ok = loc_na = date_ok = date_na = prev_ok = prev_na = team = 0
        for t in ls:
            me, boss = pub[t["record_id"]], pub[t["expected_manager_id"]]
            a, b = parse_location(me["location"]), parse_location(boss["location"])
            if a and b:
                loc_ok += a == b
            else:
                loc_na += 1
            da, db = _ym(me["start_date"]), _ym(boss["start_date"])
            if da and db:
                date_ok += (da[0], da[1] or 0) >= (db[0], db[1] or 0)
            else:
                date_na += 1
            if me["prev_employer"] and boss["prev_employer"]:
                prev_ok += me["prev_employer"] == boss["prev_employer"]
            else:
                prev_na += 1
            team += "team" in t["mess_tags"].split(";")
        n = len(ls)
        rows.append([l, f"{_pct(loc_ok, n - loc_na)} ({_pct(loc_na, n)} n/a)",
                     f"{_pct(date_ok, n - date_na)} ({_pct(date_na, n)} n/a)",
                     f"{_pct(prev_ok, n - prev_na)} ({_pct(prev_na, n)} n/a)", _pct(team, n)])
    s.append(_table(["Mess level", "Same office as boss", "Joined after boss", "Same previous employer",
                     "Team visible in title"], rows))
    s.append("\nShared previous employer is rare but, when present, very specific; office and start date are "
             "common but weak on their own. No single clue is enough, which is the point.\n")

    # 6. Example ------------------------------------------------------------------------------------------
    rng = random.Random(1)
    cid = next(c["company_id"] for c in tcomp if c["mess_level"] == "messy" and 150 < int(c["size"]) < 300)
    cname = next(c["name"] for c in companies if c["company_id"] == cid)
    sample = rng.sample([p for p in people if p["company_id"] == cid], 10)
    s.append(f"## 6. Ten raw rows from one messy company ({cname})\n")
    s.append(_table(["name", "title", "department", "location", "start_date", "prev_employer", "_truth: kind / real title_"],
                    [[p["name"], p["title"], p["department"], p["location"], p["start_date"], p["prev_employer"],
                      f"{tru[p['record_id']]['kind']} / {tru[p['record_id']]['canonical_title']} "
                      f"({LEVEL_NAMES[int(tru[p['record_id']]['level'])]})"] for p in sample]))

    # 7. Simplifications ---------------------------------------------------------------------------------
    s.append("""
## 7. Known simplifications

- One manager per person: no matrix or dotted-line reporting.
- One snapshot in time: no end dates, so ghosts are only detectable through clues (older start date, duplicated role).
- Every company has a single CEO at the top; holding companies and co-CEOs aren't modelled.
- Names and employer names are fictional; cities, sales regions, shopping centres and mine sites are real places.
- Titles are English only.
""")
    return "\n".join(s)


if __name__ == "__main__":
    DOC.write_text(build())
    print(f"wrote {DOC}")
